\set ON_ERROR_STOP on
begin;
-- Действующие правила ДМС Альфы (приказ №367 от 19.12.2025) — применяются к корпоративным
-- договорам, по которым идут программы клиники «Томск_*».
delete from coverage_rule where document_id = (select id from program_document where storage_path='programs/alfa_dms_2025-12-19.pdf');
with d as (select id, insurance_company_id from program_document where storage_path='programs/alfa_dms_2025-12-19.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', true
from d cross join (values
-- ── стоматология: п. 5.4.21.10 (всё «если иное прямо не указано в программе») ──
('ортодонтия','ортодонтические услуги и подготовка к ним','excluded','если иное прямо не указано в объёме программы страхования','п. 5.4.21.10'),
('протезирование','ортопедические услуги протезирование подготовка к протезированию','excluded','если иное прямо не указано в программе','п. 5.4.21.10'),
('имплантация','имплантация зубов подготовка к имплантации','excluded','если иное прямо не указано в программе','п. 5.4.21.10'),
('стоматология-терапия','замена пломб пломбирование по косметическим показаниям','excluded',null,'п. 5.4.21.10'),
('стоматология-терапия','восстановление коронковой части зуба при значительном разрушении','excluded','при разрушении сверх указанного в программе объёма','п. 5.4.21.10'),
('стоматология-терапия','вертикальная конденсация термопластические композиты','excluded',null,'п. 5.4.21.10'),
('стоматология-терапия','закрытие перфораций pro root','excluded',null,'п. 5.4.21.10'),
('стоматология-профилактика','глубокое фторирование','excluded',null,'п. 5.4.21.10'),
('стоматология-профилактика','отбеливание зубов снятие пигментированного налёта художественная реставрация виниры','excluded','снятие налёта — сверх объёма, указанного в программе','п. 5.4.21.10'),
('стоматология-хирургия','зубосохраняющие операции гемисекция резекция верхушки корня цистотомия','excluded',null,'п. 5.4.21.10'),
('пародонтология','лечение заболеваний тканей пародонта сверх объёма программы','excluded',null,'п. 5.4.21.10'),
('стоматология-хирургия','пластические операции в стоматологии','excluded',null,'п. 5.4.21.10'),
('стоматология-терапия','условное лечение зубов','excluded',null,'п. 5.4.21.10'),
('стоматология-профилактика','плановая санация полости рта','excluded',null,'п. 5.4.21.10'),
('стоматология-терапия','интраоральная видеокамера стоматологический микроскоп лазерные установки','excluded','если иное прямо не указано в программе','п. 5.4.21.10'),
('стоматология-профилактика','услуги в профилактических и оздоровительных целях','excluded','включая профилактику в стоматологии','п. 5.4.21.1'),
-- ── общемедицинские исключения ──
('общие-исключения','косметические эстетические услуги мозоли бородавки папилломы невусы вросший ноготь коррекция веса','excluded',null,'п. 5.4.21.2'),
('общие-исключения','психотерапия услуги психолога остеопатия','excluded',null,'п. 5.4.21.3'),
('общие-исключения','традиционная народная медицина гомеопатия гирудотерапия галотерапия экспериментальные методы','excluded',null,'п. 5.4.21.4'),
('общие-исключения','планирование семьи контрацепция вмс','excluded','кроме удаления ВМС по медицинским показаниям','п. 5.4.21.5'),
('диагностика','молекулярно-генетические исследования позитронно-эмиссионная томография','excluded',null,'п. 5.4.21.6'),
('общие-исключения','экстракорпоральные методы гемодиализ плазмаферез облучение крови озонотерапия','excluded','кроме жизненных показаний в реанимации','п. 5.4.21.7'),
('физиотерапия','индивидуальные занятия лфк аппаратный массаж гидроколонотерапия тренажёры солярий бассейн','excluded',null,'п. 5.4.21.8'),
('лекарства','специфическая иммунотерапия сит','excluded',null,'п. 5.4.21.9'),
('общие-исключения','плановые операции при нарушениях рефракции глаукоме катаракте отслойке сетчатки','excluded','включая связанное стационарное лечение и аппаратную коррекцию зрения','п. 5.4.21.11'),
('общие-исключения','кардиохирургические эндоваскулярные реконструктивные операции трансплантация органов','excluded','кроме экстренных по жизненным показаниям; пластические — кроме последствий травм в период договора','п. 5.4.21.12'),
('стационар','стационар на дому реабилитация сверх программы санаторно-курортное лечение уход','excluded',null,'п. 5.4.21.13'),
('общие-условия','услуги после установления исключённого диагноза','excluded','с момента установления диагноза услуги по нему не оплачиваются','п. 5.4'),
('общие-условия','объём определяется программой страхования','conditional','любые из перечисленных услуг оплачиваются, только если прямо указаны в объёме программы','п. 5.4.21')
) as v(sc, sp, vd, ct, cl);

select 'правил Альфа 2025: ' || count(*) from coverage_rule cr join program_document pd on pd.id=cr.document_id
 where pd.storage_path='programs/alfa_dms_2025-12-19.pdf';

-- программы клиники «Томск_*» идут по корпоративным правилам — связываем с ними
update program_alias set
  program_name = null,
  note = 'корпоративная программа договора клиники; применяются действующие Правила ДМС Альфы (приказ №367 от 19.12.2025) — они уже в базе; точный перечень услуг программы ожидается от клиники'
where insurance_company_id = (select id from insurance_company where name ilike '%Альфа%')
  and alias_norm like 'томск%';

select 'всего правил: ' || count(*) from coverage_rule;
commit;
